module TopModule(
    input clk,
    input rst_n,
    input data,
    output reg match,
    output reg not_match
);

    reg [3:0] pstate, nstate;

    parameter IDLE = 4'd0,
              P1   = 4'd1,
              P2   = 4'd2,
              P3   = 4'd3,
              P4   = 4'd4,
              P5   = 4'd5,
              F1   = 4'd6,
              F2   = 4'd7,
              F3   = 4'd8,
              F4   = 4'd9,
              F5   = 4'd10,
              M    = 4'd11,
              NM   = 4'd12;

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n)
            pstate <= IDLE;
        else
            pstate <= nstate;
    end

    always @(*) begin
        case (pstate)
            IDLE: nstate = data ? F1 : P1;
            P1:   nstate = data ? P2 : F2;
            P2:   nstate = data ? P3 : F3;
            P3:   nstate = data ? P4 : F4;
            P4:   nstate = data ? F5 : P5;
            P5:   nstate = data ? NM : M;
            F1:   nstate = F2;
            F2:   nstate = F3;
            F3:   nstate = F4;
            F4:   nstate = F5;
            F5:   nstate = NM;
            M:    nstate = data ? F1 : P1;
            NM:   nstate = data ? F1 : P1;
            default: nstate = IDLE;
        endcase
    end

    always @(*) begin
        if (!rst_n) begin
            match = 1'b0;
            not_match = 1'b0;
        end
        else begin
            match = (pstate == M);
            not_match = (pstate == NM);
        end
    end

endmodule

